-- Import des courriers départs 2026
-- Source : depart_2026.xlsx (feuille 2026), comparé à la requête déjà importée (832 lignes).
-- Ce fichier ne reprend pas 2002-2025. Il s'ajoute à import_departs_2002_2025.sql.
--
-- Colonnes Excel -> table departs :
--   N° DOSSIER        -> txt_referencecourierdepartcd (« Dossier <n> », y compris « bis »)
--                        Plusieurs personnes pour le même n° -> BE à réponses Multiples
--   DATE              -> dt_datecouriercd et dt_dateenvoicd
--   PRENOMS + NOM     -> txt_prenomNomcd et txt_destinatairecd
--   SITUATION         -> txt_lotissementcd (complétée par l'arrivée reliée si elle est vide)
--   OBJET             -> txt_objetcd
--   TF                -> txt_numTitreFonciercd
--   LOT               -> txt_numLotcd
--   SUPERFICIE/M²     -> txt_superficiecd si c'est un nombre (décimal 10,2)
--   NICAD             -> txt_NICADcd (25 car. max) et rappel dans txt_observationcd
--   ANCIEN TITRES     -> txt_NICADcd quand la cellule est un NICAD (16 chiffres).
--                        Un vrai n° de titre (avec /) va dans txt_numTitreMerecd, 20 car. max.
--   OBSERVATIONS      -> txt_observationcd
--
-- Rapprochement avec une arrivée : même titre (ou ancien titre) et même lot,
-- 15/S et S 15 étant le même lot, arrivée la plus récente avant le départ,
-- de préférence au même nom. Un visa V/LN° du ... désigne directement la référence.
-- txt_referencecourierarriveecd reprend txt_reference tel quel.
-- Catégorie Reponse à un Courrier arrivé, ou Dossier Retourne si le libellé
-- ou l'observation commence par Retour. Sans lien : Demande, Information ou
-- Transmission de Documents selon l'objet.
-- Durée = jours entre la date d'arrivée enregistrée et le départ.
-- Pas de durée si l'arrivée est un 1er janvier ou antérieure à 1990.
--
-- N° d'ordre conservés pour les 832 courriers déjà importés.
-- Le lot du n° 0581 (Abdoulaye BA) passe de 369 à 39, comme le classeur.
-- Les courriers nouveaux reçoivent la suite des numéros, dans l'ordre des dates.
-- Lignes importées : 1232
-- Dont nouvelles : 400
-- Reliées à une arrivée : 675
--
-- Catégories :
--   663  Reponse à un Courrier arrivé
--   333  (sans catégorie)
--   199  Demande
--    19  Dossier Retourne
--     9  Information
--     9  Transmission de Documents
-- Types :
--   752  BE à réponses Multiples
--   480  Individuel

SET NAMES utf8mb4;

ALTER TABLE `departs`
  MODIFY `txt_numLotcd` VARCHAR(120) NULL,
  MODIFY `txt_numTitreFonciercd` VARCHAR(255) NULL,
  MODIFY `txt_numdossiercd` VARCHAR(50) NULL,
  MODIFY `txt_observationcd` TEXT NULL;

START TRANSACTION;


COMMIT;
